            const same: any = $('results').querySelector(`[${focus.attribute}="${CSS.escape(focus.value)}"]`);
            const neighbor: any = focus.row >= 0 ? rows[Math.min(focus.row, rows.length - 1)]?.querySelector(`[${focus.attribute}]`) : null;
