    for (const dialog of dialogs) {
        dialog.addEventListener('cancel', (e: any): any => { e.preventDefault(); closeDialog(dialog); }, events);
        dialog.addEventListener('click', (e: any): any => { if (e.target === dialog) {
            const r: any = dialog.getBoundingClientRect();
            if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom)
                closeDialog(dialog);
        } }, events);
        dialog.addEventListener('close', (): any => finishDialogClose(dialog), events);
    }
    (window as any).addEventListener('admiral:apartment-favorites', refreshFavorites, events);
    (window as any).addEventListener('storage', (event: any): any => { if (event.key === 'admiral-park:favorites:v1' || event.key === null)
        refreshFavorites(event); }, events);
    if (useUrl)
        (window as any).addEventListener('popstate', (): any => { state = ({ ...defaults, sort: 'id' } as any); readUrl(); syncControls(); render(); const id: any = new URL(location.href).searchParams.get('apartment'); if (id && byId(id))
            detail(id);
        else
            config.onApartmentClose?.(); }, events);
    if (embed)
        (document as any).documentElement.classList.add('embedded');
